export function validateSpecs(){
 const returned=entry.review.filter(r=>r.verdict==="REVISE");assert.equal(specs.size,16);assert.deepEqual(new Set(specs.keys()),new Set(returned.map(r=>r.id)));
 for(const[id,s]of specs){const review=entry.review.find(r=>r.id===id);for(const k of ["cues","fairness","suggestions"])assert.equal(s.responses[k].length,review[k].length,id+" "+k+" response count");assert([3,4].includes(s.options.length));assert(s.options.every(p=>p.length===2&&p.every(v=>typeof v==="string"&&v.length)));assert.equal(s.services.length,s.options.length,id+" service count");assert.equal(s.timing.length,s.options.length,id+" timing count");assert(s.steps.length>=2);assert(!s.basicRecallIntentional);}
 return {revisions:specs.size,pass:57,notes:returned.reduce((n,r)=>n+r.cues.length+r.fairness.length+r.suggestions.length,0)};
}
